SELECT ?point ?tsid ?cls WHERE {
  ?point ref:hasName ?n .
  FILTER(CONTAINS(?n, "SupplyFan_AHU01") || ?n = "SupplyFan_AHU01")
  ?point ref:hasTimeseriesId ?tsid ; rdf:type ?cls .
}

SELECT ?point ?tsid ?cls ?n WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point ref:hasName ?n . }
  FILTER(CONTAINS(str(?point), "SupplyFan_AHU01") || (BOUND(?n) && CONTAINS(?n, "SupplyFan_AHU01")))
}

SELECT ?point ?n ?cls WHERE {
  ?point ?p ?o .
  FILTER(CONTAINS(str(?point), "SupplyFan") || CONTAINS(str(?point), "AHU01"))
  OPTIONAL { ?point ref:hasName ?n . }
}

